/** A session-local display order; each value remains the original answer-option index. */
export function orderOptions(count, random = Math.random) {
  if (!Number.isInteger(count) || count < 0) throw new RangeError('Option count must be a nonnegative integer.');
  const order = Array.from({length: count}, (_, index) => index);
  for (let index = order.length - 1; index > 0; index--) {
    const value = random();
    if (typeof value !== 'number' || !Number.isFinite(value) || value < 0 || value >= 1) {
      throw new RangeError('The option-order source must return a number from zero up to one.');
    }
    const target = Math.floor(value * (index + 1));
    [order[index], order[target]] = [order[target], order[index]];
  }
  return Object.freeze(order);
}

import { MAX_DECK_BYTES, parseDeck, serializeDeck } from './deck.mjs';

/** Stage a local file without touching the current learning session until Start. */
export function mountDeckPicker(element, bundledDeck, onStart) {
  const input = element.querySelector('#deck-file');
  const status = element.querySelector('#deck-status');
  const preview = element.querySelector('#deck-preview');
  let revision = 0;
  let pending = null;

  function message(text, error = false) {
    status.textContent = text;
    status.classList.toggle('deck-error', error);
  }
  function clearPreview() {
    pending = null;
    preview.replaceChildren();
    preview.hidden = true;
  }
  function showPreview(deck, source) {
    pending = deck;
    preview.hidden = false;
    preview.innerHTML = '<h3 id="deck-preview-title" tabindex="-1"></h3><p class="deck-preview-count"></p><p class="deck-preview-attribution"></p><p class="deck-preview-license"></p><details class="deck-questions"><summary>Preview question prompts</summary><ol></ol></details><p class="deck-replace-note">Starting this deck replaces the current session and its practice answers. Your file stays on this device.</p><div class="deck-actions"><button class="primary-button" id="start-deck">Start this deck</button><button class="reset-button" id="cancel-deck">Cancel preview</button></div>';
    preview.querySelector('h3').textContent = deck.title;
    preview.querySelector('.deck-preview-count').textContent = `${source} · ${deck.items.length} questions · ${deck.concepts.length} concepts`;
    preview.querySelector('.deck-preview-attribution').textContent = `Attribution supplied in the deck: ${deck.attribution}`;
    preview.querySelector('.deck-preview-license').textContent = `License supplied in the deck: ${deck.license}`;
    const list = preview.querySelector('ol');
    for (const item of deck.items) {
      const row = document.createElement('li');
      const prompt = document.createElement('strong');
      prompt.textContent = item.prompt;
      const concept = document.createElement('p');
      concept.textContent = `${item.concept} · ${item.prerequisites.length ? `Prerequisites: ${item.prerequisites.join(', ')}` : 'No prerequisites'}`;
      row.append(prompt, concept);
      list.append(row);
    }
    preview.querySelector('#cancel-deck').addEventListener('click', () => {
      revision++;
      clearPreview();
      input.value = '';
      message('Preview cancelled. Your current session is unchanged.');
      input.focus();
    });
    preview.querySelector('#start-deck').addEventListener('click', () => {
      if (pending !== deck) return;
      const selected = deck;
      revision++;
      clearPreview();
      input.value = '';
      onStart(selected);
      message(`Started “${selected.title}”. This lesson stays in this tab until you reload or choose another deck.`);
    });
    message('Deck ready to preview. Your current session continues until you choose Start this deck.');
    preview.querySelector('h3').focus();
  }

  input.addEventListener('change', async () => {
    const file = input.files?.[0];
    if (!file) return;
    const request = ++revision;
    clearPreview();
    message('Reading the local deck…');
    try {
      if (file.size > MAX_DECK_BYTES) throw new Error('Choose a JSON deck no larger than 256 KiB.');
      let text;
      try { text = await file.text(); }
      catch { throw new Error('The file could not be read. Choose it again.'); }
      if (request !== revision) return;
      showPreview(parseDeck(text), file.name);
    } catch (error) {
      if (request !== revision) return;
      clearPreview();
      message(`${error.message} Your current session is unchanged.`, true);
      input.value = '';
      status.focus();
    }
  });
  element.querySelector('#use-bundled-deck').addEventListener('click', () => {
    revision++;
    showPreview(bundledDeck, 'Bundled example');
  });
  element.querySelector('#download-deck').addEventListener('click', () => {
    const url = URL.createObjectURL(new Blob([serializeDeck(bundledDeck)], {type: 'application/json'}));
    const link = document.createElement('a');
    link.href = url;
    link.download = 'recallweave-example-deck.json';
    link.click();
    setTimeout(() => URL.revokeObjectURL(url), 0);
    message('Example deck downloaded. Edit a copy, then choose it here to preview it.');
  });
}

/** Local lesson content. Imported data cannot replace the model or run code. */
export const DECK_FORMAT = 'recallweave-deck/1';
export const MAX_DECK_BYTES = 262144;

function deckRecord(value, path) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new Error(`${path} must be an object.`);
  }
  return value;
}

function deckText(value, path, limit) {
  if (typeof value !== 'string' || !value.trim() || value.length > limit) {
    throw new Error(`${path} must be nonempty text of at most ${limit} characters.`);
  }
  return value;
}

function deckList(value, path, minimum, maximum) {
  if (!Array.isArray(value) || value.length < minimum || value.length > maximum) {
    throw new Error(`${path} must contain ${minimum}–${maximum} entries.`);
  }
  return value;
}

/** Validate and copy only the content fields used by the existing lesson runtime. */
export function validateDeck(value) {
  const input = deckRecord(value, 'Deck');
  if (input.format !== undefined && input.format !== DECK_FORMAT) {
    throw new Error(`Unsupported deck format. Use ${DECK_FORMAT}.`);
  }
  const title = deckText(input.title, 'title', 160);
  const attribution = deckText(input.attribution, 'attribution', 2000);
  const license = deckText(input.license, 'license', 2000);
  const concepts = deckList(input.concepts, 'concepts', 1, 32).map((concept, index) =>
    deckText(concept, `concepts[${index}]`, 80));
  if (new Set(concepts).size !== concepts.length) throw new Error('Concept names must be unique.');
  const knownConcepts = new Set(concepts);
  const ids = new Set();
  const coveredConcepts = new Set();
  const links = new Map(concepts.map(concept => [concept, new Set()]));
  const items = deckList(input.items, 'items', 1, 100).map((value, index) => {
    const path = `items[${index}]`;
    const item = deckRecord(value, path);
    const id = deckText(item.id, `${path}.id`, 80);
    if (ids.has(id)) throw new Error(`${path}.id duplicates another question ID.`);
    ids.add(id);
    const concept = deckText(item.concept, `${path}.concept`, 80);
    if (!knownConcepts.has(concept)) throw new Error(`${path}.concept is not in concepts.`);
    coveredConcepts.add(concept);
    const prerequisites = deckList(item.prerequisites, `${path}.prerequisites`, 0, 31).map((name, p) => {
      deckText(name, `${path}.prerequisites[${p}]`, 80);
      if (!knownConcepts.has(name)) throw new Error(`${path}.prerequisites contains an unknown concept.`);
      if (name === concept) throw new Error(`${path} cannot require its own concept.`);
      links.get(concept).add(name);
      return name;
    });
    if (new Set(prerequisites).size !== prerequisites.length) throw new Error(`${path}.prerequisites contains a duplicate.`);
    const options = deckList(item.options, `${path}.options`, 2, 6).map((option, o) =>
      deckText(option, `${path}.options[${o}]`, 1000));
    if (new Set(options).size !== options.length) throw new Error(`${path}.options must be distinct.`);
    if (!Number.isInteger(item.answer) || item.answer < 0 || item.answer >= options.length) {
      throw new Error(`${path}.answer must be a zero-based index of an option.`);
    }
    return Object.freeze({
      id, concept, prerequisites: Object.freeze(prerequisites),
      prompt: deckText(item.prompt, `${path}.prompt`, 2000),
      options: Object.freeze(options), answer: item.answer,
      explanation: deckText(item.explanation, `${path}.explanation`, 4000),
      transfer: deckText(item.transfer, `${path}.transfer`, 2000)
    });
  });
  if (coveredConcepts.size !== concepts.length) throw new Error('Every concept must have at least one question.');
  const visiting = new Set();
  const visited = new Set();
  const visit = concept => {
    if (visiting.has(concept)) throw new Error('Prerequisite links must not form a cycle.');
    if (visited.has(concept)) return;
    visiting.add(concept);
    for (const prerequisite of links.get(concept)) visit(prerequisite);
    visiting.delete(concept);
    visited.add(concept);
  };
  concepts.forEach(visit);
  return Object.freeze({
    format: DECK_FORMAT, title, attribution, license,
    concepts: Object.freeze(concepts), items: Object.freeze(items)
  });
}

/** The same size limit applies to a File and to programmatically supplied UTF-8 JSON. */
export function parseDeck(text) {
  if (typeof text !== 'string' || new TextEncoder().encode(text).length > MAX_DECK_BYTES) {
    throw new Error('Choose a JSON deck no larger than 256 KiB.');
  }
  let value;
  try { value = JSON.parse(text); }
  catch { throw new Error('The file is not valid JSON. Check its commas, quotes and brackets.'); }
  return validateDeck(value);
}

/** Export the existing bundled lesson as an editable example of the same contract. */
export function serializeDeck(deck) {
  return JSON.stringify(validateDeck(deck), null, 2) + '\n';
}

/**
 * Transparent Bayesian Knowledge Tracing and adaptive item selection.
 * Parameters are pedagogical defaults, not fitted or validated estimates.
 * @typedef {{id:string, concept:string, prerequisites:string[], options:string[], answer:number, prompt:string, explanation:string, transfer:string}} Item
 * @typedef {{initial:number, learn:number, guess:number, slip:number}} BktParameters
 */
export const DEFAULT_BKT = Object.freeze({ initial: 0.22, learn: 0.18, guess: 0.2, slip: 0.1 });
const clamp = (value, min = 0, max = 1) => Math.min(max, Math.max(min, value));

/** Bernoulli entropy in bits. @param {number} p */
export function entropy(p) {
  const q = clamp(p);
  if (q === 0 || q === 1) return 0;
  return -q * Math.log2(q) - (1 - q) * Math.log2(1 - q);
}

/**
 * One BKT update. Correctness is evidence, not certainty; a guess and a slip remain possible.
 * @param {number} prior
 * @param {boolean} correct
 * @param {BktParameters} parameters
 */
export function updateMastery(prior, correct, parameters = DEFAULT_BKT) {
  const p = clamp(prior);
  const { guess, slip, learn } = parameters;
  for (const [key, value] of Object.entries(parameters)) {
    if (!Number.isFinite(value) || value < 0 || value > 1) throw new RangeError(`${key} must be in [0,1]`);
  }
  const pCorrect = p * (1 - slip) + (1 - p) * guess;
  const posterior = correct ? p * (1 - slip) / pCorrect : p * slip / (p * slip + (1 - p) * (1 - guess));
  return clamp(posterior + (1 - posterior) * learn);
}

/** Expected reduction in uncertainty from an item response under its concept mastery.
 * @param {number} mastery
 * @param {BktParameters} parameters
 */
export function expectedInformationGain(mastery, parameters = DEFAULT_BKT) {
  const p = clamp(mastery);
  const { guess, slip } = parameters;
  const pCorrect = p * (1 - slip) + (1 - p) * guess;
  const correctPosterior = p * (1 - slip) / pCorrect;
  const wrongPosterior = p * slip / (p * slip + (1 - p) * (1 - guess));
  return Math.max(0, entropy(p) - pCorrect * entropy(correctPosterior) - (1 - pCorrect) * entropy(wrongPosterior));
}

/**
 * Select an unseen item maximizing uncertainty reduction plus prerequisite repair.
 * Tie-break is stable by item id, making the choice reproducible.
 * @param {Item[]} items
 * @param {Set<string>} asked
 * @param {Record<string,number>} mastery
 * @param {BktParameters} parameters
 * @returns {Item|null}
 */
export function selectNextItem(items, asked, mastery, parameters = DEFAULT_BKT) {
  const candidates = items.filter(item => !asked.has(item.id));
  if (!candidates.length) return null;
  const score = item => {
    const m = mastery[item.concept] ?? parameters.initial;
    // Prefer a weak concept that unlocks several still-unanswered downstream ideas.
    const downstream = candidates.filter(next => next.id !== item.id && next.prerequisites.includes(item.concept)).length;
    const prerequisiteRepair = (1 - m) * Math.min(3, downstream) * 0.12;
    return expectedInformationGain(m, parameters) + prerequisiteRepair;
  };
  return candidates.sort((a, b) => score(b) - score(a) || a.id.localeCompare(b.id))[0];
}

/** Clone session probabilities so learners' local run has no shared state. */
export function initialMastery(concepts, parameters = DEFAULT_BKT) {
  return Object.fromEntries(concepts.map(concept => [concept, parameters.initial]));
}

/**
 * Reproducible toy learner run; simulated evidence is never real learner data.
 * @param {Item[]} items
 * @param {string[]} concepts
 * @param {Record<string,number>} latentKnowledge simulated probability of knowing each concept
 * @param {boolean} adaptive use the information-gain selector, or fixed deck order
 * @param {number} seed deterministic pseudo-random seed
 */
export function runLearnerSimulation(items, concepts, latentKnowledge, adaptive = true, seed = 20261005) {
  let state = seed >>> 0 || 1;
  const random = () => {
    state ^= state << 13; state ^= state >>> 17; state ^= state << 5;
    return (state >>> 0) / 4294967296;
  };
  const stateByConcept = initialMastery(concepts);
  const asked = new Set();
  const trace = [];
  while (asked.size < items.length) {
    const item = adaptive ? selectNextItem(items, asked, stateByConcept) : items.find(candidate => !asked.has(candidate.id));
    const knowledge = clamp(latentKnowledge[item.concept] ?? 0.5);
    const correct = random() < 0.18 + knowledge * 0.72;
    asked.add(item.id);
    stateByConcept[item.concept] = updateMastery(stateByConcept[item.concept], correct);
    trace.push({ item: item.id, concept: item.concept, correct });
  }
  const meanEstimatedMastery = concepts.reduce((sum, concept) => sum + stateByConcept[concept], 0) / concepts.length;
  return { trace, mastery: stateByConcept, meanEstimatedMastery };
}

/**
 * A local review snapshot and one bounded practice round.
 * Practice never updates the original answers or the knowledge model.
 */

function validChoice(item, choice) {
  if (!Number.isInteger(choice) || choice < 0 || choice >= item.options.length) {
    throw new RangeError('Choose one of this question’s answer options.');
  }
}

/** Keep the first-attempt order, chosen answer and explanation available for review. */
export function createReview(items, answers) {
  const byId = new Map(items.map(item => [item.id, item]));
  const seen = new Set();
  return Object.freeze(answers.map(answer => {
    const item = byId.get(answer.item);
    if (!item || seen.has(item.id)) throw new RangeError('Review needs one first answer per known question.');
    seen.add(item.id);
    validChoice(item, answer.choice);
    return Object.freeze({
      id: item.id,
      concept: item.concept,
      prompt: item.prompt,
      options: Object.freeze([...item.options]),
      answer: item.answer,
      choice: answer.choice,
      correct: answer.choice === item.answer,
      explanation: item.explanation,
      transfer: item.transfer
    });
  }));
}

/** Each initially missed question gets one retry, in its original session order. */
export function beginPractice(review) {
  return Object.freeze({
    items: Object.freeze(review.filter(item => !item.correct)),
    answers: Object.freeze([])
  });
}

export function currentPracticeItem(round) {
  return round.items[round.answers.length] ?? null;
}

/** Return new practice state; both the review and earlier round states stay intact. */
export function answerPractice(round, itemId, choice) {
  const item = currentPracticeItem(round);
  if (!item || item.id !== itemId) throw new RangeError('Only the current unanswered practice question can be answered.');
  validChoice(item, choice);
  return Object.freeze({
    items: round.items,
    answers: Object.freeze([...round.answers, Object.freeze({item: item.id, choice, correct: choice === item.answer})])
  });
}

import { APPLICATION_PROMPT, reflectionSnapshot } from './reflections.mjs';

/** Build local, readable study notes from a completed first session and separate practice. */
export function createStudyNotes({ deck, review, mastery, practice = null, reflections = null, exportedAt = new Date(), conceptLabel = id => id, applicationPrompt = APPLICATION_PROMPT }) {
  if (!Array.isArray(review) || review.length !== deck.items.length || review.length === 0) {
    throw new RangeError('Finish the learning session before saving study notes.');
  }
  const known = new Set(deck.items.map(item => item.id));
  const seen = new Set();
  for (const item of review) {
    if (!known.has(item.id) || seen.has(item.id)) throw new RangeError('Study notes need every first answer exactly once.');
    seen.add(item.id);
    for (const choice of [item.choice, item.answer]) {
      if (!Number.isInteger(choice) || choice < 0 || choice >= item.options.length) {
        throw new RangeError('Study notes need the recorded answer choice.');
      }
    }
  }
  const missed = review.filter(item => item.choice !== item.answer);
  const retries = practice?.answers ?? [];
  if (retries.length > missed.length) throw new RangeError('Practice must remain separate from the first session.');
  retries.forEach((retry, index) => {
    const item = missed[index];
    if (retry.item !== item.id || !Number.isInteger(retry.choice) || retry.choice < 0 || retry.choice >= item.options.length) {
      throw new RangeError('Study notes need the recorded practice order and choices.');
    }
  });
  const savedAt = new Date(exportedAt);
  if (!Number.isFinite(savedAt.getTime())) throw new RangeError('Study notes need a valid save time.');
  const notebook = reflections === null ? null : reflectionSnapshot(reflections, deck.items);
  if (notebook && (typeof applicationPrompt !== 'string' || !applicationPrompt.trim())) {
    throw new TypeError('Study notes need the application prompt shown in this session.');
  }
  const reflectionById = new Map(notebook?.notes.map(note => [note.item, note.text]));
  const lines = [
    'RecallWeave — study notes',
    deck.title,
    `Saved: ${savedAt.toISOString()}`,
    '',
    'FIRST SESSION',
    `${review.length - missed.length} of ${review.length} connections correct on the first try.`,
    'This count describes this session; it is not a measure of your ability.',
    '',
    'ESTIMATED MASTERY — MODEL STATE, NOT A GRADE',
    'These estimates come from the demo’s learning model. They are not a validated assessment.',
    'Practice does not change the first-session estimates.'
  ];
  for (const concept of deck.concepts) {
    const value = mastery[concept];
    if (typeof value !== 'number' || !Number.isFinite(value) || value < 0 || value > 1) {
      throw new RangeError('Study notes need the original model estimates.');
    }
    lines.push(`${conceptLabel(concept)}: ${Math.round(value * 100)}%`);
  }
  lines.push('', 'PRACTICE');
  if (!missed.length) lines.push('No missed connections in the first session.');
  else if (!practice) lines.push(`Not started. ${missed.length} missed ${missed.length === 1 ? 'connection is' : 'connections are'} available for practice.`);
  else {
    const correct = retries.filter((retry, index) => retry.choice === missed[index].answer).length;
    lines.push(`${retries.length === missed.length ? 'Complete' : 'Paused'}: ${retries.length} of ${missed.length} practice answers recorded; ${correct} correct on retry.`);
  }
  lines.push('Practice follows the explanations and is recorded separately from the first answers.', '', 'REVIEW THE CONNECTIONS');
  const retryById = new Map(retries.map(retry => [retry.item, retry]));
  review.forEach((item, index) => {
    const retry = retryById.get(item.id);
    lines.push(
      '',
      `${index + 1}. ${item.prompt}`,
      `Concept: ${conceptLabel(item.concept)}`,
      `Your first answer: ${item.options[item.choice]}`,
      `First try: ${item.choice === item.answer ? 'correct' : 'needs review'}`,
      `Correct answer: ${item.options[item.answer]}`,
      `Explanation: ${item.explanation}`,
      `Apply the idea: ${item.transfer}`
    );
    if (notebook) {
      const text = reflectionById.get(item.id);
      lines.push('Your explanation — reflection, not scored:');
      lines.push(...(text ? text.split('\n').map(line => `  > ${line}`) : ['  Not written.']));
    }
    if (retry) {
      lines.push(`Practice answer: ${item.options[retry.choice]}`, `Practice result: ${retry.choice === item.answer ? 'correct on retry' : 'keep reviewing'}`);
    } else if (item.choice !== item.answer) lines.push('Practice answer: not recorded.');
  });
  if (notebook) {
    lines.push('', 'YOUR APPLICATION REFLECTION — NOT SCORED');
    lines.push(`Prompt: ${applicationPrompt}`);
    lines.push(...(notebook.application ? notebook.application.split('\n').map(line => `  > ${line}`) : ['Not written.']));
  }
  lines.push('', 'DECK ATTRIBUTION', deck.attribution, deck.license, '', 'Saved from this browser session. The download does not upload the session or restore it after a refresh.');
  return Object.freeze({
    filename: `recallweave-study-notes-${savedAt.toISOString().slice(0, 10)}.txt`,
    mediaType: 'text/plain;charset=utf-8',
    text: `${lines.join('\n')}\n`
  });
}

import { createTraceArchive, readTraceArchive, TRACE_ARCHIVE_MAX_BYTES } from './trace-archive.mjs';

/** Explicit local download and preview/restore; the owner supplies the sole state-changing callback. */
export function mountTraceArchive({container, getDeck, getTrace, restoreTrace}) {
  container.innerHTML = '<details id="trace-archive-panel"><summary>Keep or restore a learning trace</summary>'
    + '<p>Save completed first answers and any practice progress. To return later, open the same course and choose the saved file.</p>'
    + '<button type="button" class="reset-button" id="save-trace-button" aria-describedby="save-trace-status">Download trace (.json)</button>'
    + '<p id="save-trace-status" role="status"></p>'
    + '<label for="trace-file">Choose a saved learning trace (.json, up to 2 MiB)</label>'
    + '<input type="file" id="trace-file" accept=".json,application/json" aria-describedby="trace-restore-status">'
    + '<p id="trace-restore-status" role="status">A preview appears before anything is restored.</p>'
    + '<section id="trace-preview" hidden aria-labelledby="trace-preview-title">'
    + '<h3 id="trace-preview-title" tabindex="-1">Preview saved trace</h3><p id="trace-preview-summary"></p>'
    + '<p>Restoring replaces the first answers and practice progress in this tab. This file contains answers and practice progress only; any reflections already in this tab stay as they are.</p>'
    + '<div class="trace-archive-actions"><button type="button" class="primary-button" id="restore-trace-confirm">Restore these answers</button>'
    + '<button type="button" class="reset-button" id="restore-trace-cancel">Cancel</button></div></section></details>';
  const query = selector => container.querySelector(selector);
  const saveButton = query('#save-trace-button');
  const saveStatus = query('#save-trace-status');
  const input = query('#trace-file');
  const restoreStatus = query('#trace-restore-status');
  const preview = query('#trace-preview');
  let generation = 0;
  let pending = null;
  let readingStamp = null;
  let previousCanSave;

  function stamp() {
    const {answers, mastery, practice} = getTrace();
    return JSON.stringify({deck: getDeck(), answers, mastery, practice});
  }
  function clearPreview(message, resetInput = true) {
    generation++;
    pending = null;
    readingStamp = null;
    preview.hidden = true;
    if (resetInput) input.value = '';
    if (message) restoreStatus.textContent = message;
  }
  function refresh() {
    const trace = getTrace();
    const canSave = trace.answers.length > 0 && trace.answers.length === getDeck().items.length;
    saveButton.disabled = !canSave;
    if (canSave !== previousCanSave) {
      saveStatus.textContent = canSave
        ? 'Download a trace to return to these answers and recorded practice later.'
        : 'Finish the first session before saving a trace.';
      previousCanSave = canSave;
    }
    const expected = pending?.stamp ?? readingStamp;
    if (expected !== null && expected !== undefined && expected !== stamp()) {
      clearPreview('Your lesson changed. Choose the trace file again to preview it against the current session.');
    }
  }

  saveButton.addEventListener('click', () => {
    let url;
    try {
      const archive = createTraceArchive({deck: getDeck(), ...getTrace()});
      url = URL.createObjectURL(new Blob([archive.text], {type: archive.mediaType}));
      const link = document.createElement('a');
      link.href = url;
      link.download = archive.filename;
      document.body.append(link);
      try { link.click(); } finally { link.remove(); }
      saveStatus.textContent = 'Download requested. Check your browser’s downloads for the learning trace. Your answers are still here.';
    } catch {
      saveStatus.textContent = 'The trace could not be prepared. Your answers are still here; try the download again.';
    } finally {
      if (url) setTimeout(() => URL.revokeObjectURL(url), 10000);
    }
  });

  input.addEventListener('change', async () => {
    const file = input.files?.[0];
    clearPreview(undefined, false);
    if (!file) {
      restoreStatus.textContent = 'No trace selected. Your current lesson is unchanged.';
      return;
    }
    const ticket = generation;
    readingStamp = stamp();
    const beforeRead = readingStamp;
    restoreStatus.textContent = 'Reading the selected trace…';
    try {
      if (file.size > TRACE_ARCHIVE_MAX_BYTES) throw new RangeError('Choose a learning trace file no larger than 2 MiB.');
      const text = await file.text();
      if (ticket !== generation) return;
      if (beforeRead !== stamp()) {
        clearPreview('Your lesson changed. Choose the trace file again to preview it against the current session.');
        return;
      }
      const state = readTraceArchive(text, getDeck());
      pending = {state, stamp: beforeRead};
      readingStamp = null;
      const summary = state.summary;
      const practiceText = !summary.practiceTotal ? 'No missed connections need practice.'
        : !summary.practiceStarted ? 'Practice not started: ' + summary.practiceTotal + ' missed connections.'
        : 'Practice: ' + summary.practiceAnswers + ' of ' + summary.practiceTotal + ' answers recorded.';
      query('#trace-preview-summary').textContent = state.title + ' — saved ' + state.savedAt
        + '. First try: ' + summary.correctFirst + ' of ' + summary.firstAnswers + ' connections correct. ' + practiceText;
      preview.hidden = false;
      restoreStatus.textContent = 'Preview ready. Your current lesson is unchanged until you restore.';
      query('#trace-preview-title').focus();
    } catch (error) {
      if (ticket !== generation) return;
      clearPreview((error instanceof RangeError ? error.message : 'This trace could not be read.') + ' Your current lesson is unchanged.');
    }
  });

  query('#restore-trace-cancel').addEventListener('click', () => {
    clearPreview('Restore canceled. Your current lesson is unchanged.');
    input.focus();
  });
  query('#restore-trace-confirm').addEventListener('click', () => {
    if (!pending) return;
    if (pending.stamp !== stamp()) {
      clearPreview('Your lesson changed. Choose the trace file again before restoring.');
      input.focus();
      return;
    }
    const state = pending.state;
    clearPreview();
    restoreTrace(state);
    refresh();
    restoreStatus.textContent = 'Trace restored. Review your first answers and resume any remaining practice from the learning trace.';
  });
  refresh();
  return Object.freeze({refresh});
}

import { DEFAULT_BKT, initialMastery, updateMastery } from './knowledge.mjs';
import { answerPractice, beginPractice, createReview } from './review.mjs';

export const TRACE_ARCHIVE_MAX_BYTES = 2 * 1024 * 1024;
const TRACE_ARCHIVE_FORMAT = 'recallweave.learning-trace';
const TRACE_ARCHIVE_MODEL = Object.freeze({name: 'recallweave-bkt-v1', parameters: DEFAULT_BKT});

function traceRecord(value, keys) {
  return value !== null && typeof value === 'object' && !Array.isArray(value)
    && JSON.stringify(Object.keys(value).sort()) === JSON.stringify([...keys].sort());
}

function traceCanonical(value) {
  if (Array.isArray(value)) return '[' + value.map(traceCanonical).join(',') + ']';
  if (value !== null && typeof value === 'object') {
    return '{' + Object.keys(value).sort().map(key => JSON.stringify(key) + ':' + traceCanonical(value[key])).join(',') + '}';
  }
  return JSON.stringify(value);
}

function traceReplay(document, deck) {
  if (!traceRecord(document, ['format', 'version', 'savedAt', 'deck', 'model', 'firstAnswers', 'mastery', 'practice'])
      || document.format !== TRACE_ARCHIVE_FORMAT || document.version !== 1) {
    throw new RangeError('This learning trace format is not supported.');
  }
  if (typeof document.savedAt !== 'string' || document.savedAt.length !== 24
      || !Number.isFinite(Date.parse(document.savedAt))
      || new Date(document.savedAt).toISOString() !== document.savedAt) {
    throw new RangeError('This learning trace has an invalid save time.');
  }
  // Archived course content is only compared; restoration always uses the already loaded deck.
  if (traceCanonical(document.deck) !== traceCanonical(deck)) {
    throw new RangeError('This trace belongs to a different course or course version. Load its course, then choose this file again.');
  }
  if (traceCanonical(document.model) !== traceCanonical(TRACE_ARCHIVE_MODEL)) {
    throw new RangeError('This trace uses a different learning model.');
  }
  if (!Array.isArray(document.firstAnswers) || document.firstAnswers.length === 0
      || document.firstAnswers.length !== deck.items.length) {
    throw new RangeError('This file does not contain a complete first session.');
  }
  if (!document.firstAnswers.every(answer => traceRecord(answer, ['item', 'choice']))) {
    throw new RangeError('This trace has invalid first answers.');
  }
  let review;
  try { review = createReview(deck.items, document.firstAnswers); }
  catch { throw new RangeError('This trace has invalid first answers.'); }
  const mastery = initialMastery(deck.concepts);
  const answers = Object.freeze(review.map(item => {
    mastery[item.concept] = updateMastery(mastery[item.concept], item.correct);
    return Object.freeze({item: item.id, concept: item.concept, choice: item.choice, correct: item.correct});
  }));
  if (!traceRecord(document.mastery, deck.concepts)
      || deck.concepts.some(concept => !Number.isFinite(document.mastery[concept]) || document.mastery[concept] !== mastery[concept])) {
    throw new RangeError('This trace does not preserve the original model estimates.');
  }
  let practice = null;
  if (document.practice !== null) {
    if (!traceRecord(document.practice, ['answers']) || !Array.isArray(document.practice.answers)) {
      throw new RangeError('This trace has invalid practice progress.');
    }
    practice = beginPractice(review);
    try {
      for (const answer of document.practice.answers) {
        if (!traceRecord(answer, ['item', 'choice'])) throw new RangeError();
        practice = answerPractice(practice, answer.item, answer.choice);
      }
    } catch { throw new RangeError('This trace has invalid practice progress.'); }
  }
  const missed = review.filter(item => !item.correct).length;
  return Object.freeze({
    savedAt: document.savedAt,
    title: deck.title,
    answers,
    mastery: Object.freeze(mastery),
    review,
    practice,
    summary: Object.freeze({
      firstAnswers: answers.length,
      correctFirst: answers.length - missed,
      practiceStarted: practice !== null,
      practiceAnswers: practice?.answers.length ?? 0,
      practiceTotal: missed
    })
  });
}

/** Read bounded JSON into immutable state without changing the current lesson. */
export function readTraceArchive(text, deck) {
  if (typeof text !== 'string' || new TextEncoder().encode(text).byteLength > TRACE_ARCHIVE_MAX_BYTES) {
    throw new RangeError('Choose a learning trace file no larger than 2 MiB.');
  }
  let document;
  try { document = JSON.parse(text); }
  catch { throw new RangeError('This file is not valid learning trace JSON.'); }
  return traceReplay(document, deck);
}

/** Save completed first answers and one separate practice round, including full precision estimates. */
export function createTraceArchive({deck, answers, mastery, practice = null, savedAt = new Date()}) {
  if (!Array.isArray(answers)) throw new RangeError('Finish the first session before saving a trace.');
  const when = new Date(savedAt);
  if (!Number.isFinite(when.getTime())) throw new RangeError('A learning trace needs a valid save time.');
  const document = {
    format: TRACE_ARCHIVE_FORMAT,
    version: 1,
    savedAt: when.toISOString(),
    deck,
    model: TRACE_ARCHIVE_MODEL,
    firstAnswers: answers.map(answer => ({item: answer.item, choice: answer.choice})),
    mastery,
    practice: practice === null ? null : {
      answers: practice.answers.map(answer => ({item: answer.item, choice: answer.choice}))
    }
  };
  const text = JSON.stringify(document, null, 2) + '\n';
  const restored = readTraceArchive(text, deck);
  if (practice !== null && traceCanonical(practice.items.map(item => item.id))
      !== traceCanonical(restored.practice.items.map(item => item.id))) {
    throw new RangeError('This trace has invalid practice progress.');
  }
  return Object.freeze({
    filename: 'recallweave-learning-trace-' + when.toISOString().slice(0, 10) + '.json',
    mediaType: 'application/json;charset=utf-8',
    text
  });
}

/** Learner-authored notes for this session, separate from answers and model state. */
export const APPLICATION_PROMPT = 'Trace energy from sunlight to a cell doing work. Where does the form of energy change, and what molecule transfers it to cellular processes?';

function freezeReflections(notes, application) {
  return Object.freeze({
    notes: Object.freeze(notes.map(note => Object.freeze({...note}))),
    application
  });
}

export function createReflections(items) {
  const ids = items.map(item => item.id);
  if (ids.some(id => typeof id !== 'string' || !id.trim()) || new Set(ids).size !== ids.length) {
    throw new RangeError('Reflections need a distinct identity for every question.');
  }
  return freezeReflections(ids.map(item => ({item, text: ''})), '');
}

export function itemReflection(reflections, itemId) {
  const note = reflections.notes.find(note => note.item === itemId);
  if (!note) throw new RangeError('Choose a question from this session.');
  return note.text;
}

export function updateReflection(reflections, itemId, text) {
  if (typeof text !== 'string') throw new TypeError('A reflection must be text.');
  itemReflection(reflections, itemId);
  return freezeReflections(reflections.notes.map(note =>
    note.item === itemId ? {item: itemId, text} : note), reflections.application);
}

export function updateApplicationReflection(reflections, text) {
  if (typeof text !== 'string') throw new TypeError('A reflection must be text.');
  return freezeReflections(reflections.notes, text);
}

/** Bind exported notes to question identities, regardless of the adaptive review order. */
export function reflectionSnapshot(reflections, items) {
  const expected = createReflections(items);
  if (!Array.isArray(reflections?.notes) || typeof reflections?.application !== 'string') {
    throw new RangeError('Study notes need the reflections from this session.');
  }
  const byId = new Map();
  for (const note of reflections.notes) {
    if (!note || typeof note.item !== 'string' || typeof note.text !== 'string' || byId.has(note.item)) {
      throw new RangeError('Study notes need one reflection field per question.');
    }
    byId.set(note.item, note.text);
  }
  if (byId.size !== expected.notes.length || expected.notes.some(note => !byId.has(note.item))) {
    throw new RangeError('Study notes need the reflections from this session’s questions.');
  }
  return freezeReflections(expected.notes.map(({item}) => ({item, text: byId.get(item)})), reflections.application);
}

import { createLessonArchive, readLessonArchive, LESSON_ARCHIVE_MAX_BYTES } from './lesson-archive.mjs';

/** The caller owns lesson state; reading and previewing a file never change it. */
export function mountLessonArchive({container, getDeck, getLesson, resumeLesson, getSessionRevision = () => 0}) {
  container.innerHTML = '<details id="lesson-archive-panel"><summary>Save or resume an unfinished lesson</summary>'
    + '<p>Save your place, answers, and answer ordering in a file. To continue later, open the same course and choose that file.</p>'
    + '<button type="button" class="reset-button" id="save-lesson-button" aria-describedby="save-lesson-status">Save lesson (.json)</button>'
    + '<p id="save-lesson-status" role="status"></p>'
    + '<label for="lesson-file">Choose a saved unfinished lesson (.json, up to 2 MiB)</label>'
    + '<input type="file" id="lesson-file" accept=".json,application/json" aria-describedby="lesson-restore-status">'
    + '<p id="lesson-restore-status" role="status">A preview appears before anything is resumed.</p>'
    + '<section id="lesson-preview" class="lesson-preview" hidden aria-labelledby="lesson-preview-title">'
    + '<h3 id="lesson-preview-title" tabindex="-1">Preview saved lesson</h3><p id="lesson-preview-summary"></p>'
    + '<p>Resuming replaces the lesson answers and practice progress in this tab. Any reflections already in this tab stay as they are.</p>'
    + '<div class="trace-archive-actions"><button type="button" class="primary-button" id="resume-lesson-confirm">Resume this lesson</button>'
    + '<button type="button" class="reset-button" id="resume-lesson-cancel">Cancel</button></div></section></details>';
  const query = selector => container.querySelector(selector);
  const saveButton = query('#save-lesson-button');
  const saveStatus = query('#save-lesson-status');
  const input = query('#lesson-file');
  const restoreStatus = query('#lesson-restore-status');
  const preview = query('#lesson-preview');
  let generation = 0, pending = null, readingStamp = null, previousSaveState;

  // A fresh Start invalidates pending work even if its course and state are equal.
  // This transient revision is never included in the saved lesson file.
  const stamp = () => JSON.stringify({revision: getSessionRevision(), deck: getDeck(), lesson: getLesson()});
  function clearPreview(message, resetInput = true) {
    generation++;
    pending = null;
    readingStamp = null;
    preview.hidden = true;
    if (resetInput) input.value = '';
    if (message) restoreStatus.textContent = message;
  }
  function changed() {
    clearPreview('Your lesson changed. Choose the saved file again to preview it against the current lesson.');
  }
  function refresh() {
    const lesson = getLesson();
    const complete = lesson.answers.length >= getDeck().items.length;
    const started = ['question', 'feedback'].includes(lesson.presentation?.phase);
    const saveState = complete ? 'complete' : started ? 'started' : 'unstarted';
    saveButton.disabled = saveState !== 'started';
    if (saveState !== previousSaveState) {
      saveStatus.textContent = complete
        ? 'This lesson is complete. Use the learning trace below to save its answers and practice progress.'
        : started ? 'Save a file to return to this question or feedback later. Your lesson stays open.'
          : 'Start a lesson to save your place, even before answering its first question.';
      previousSaveState = saveState;
    }
    const expected = pending?.stamp ?? readingStamp;
    if (expected !== null && expected !== undefined && expected !== stamp()) changed();
  }

  saveButton.addEventListener('click', () => {
    if (saveButton.disabled) return;
    let url;
    try {
      const archive = createLessonArchive({deck: getDeck(), ...getLesson()});
      url = URL.createObjectURL(new Blob([archive.text], {type: archive.mediaType}));
      const link = document.createElement('a');
      link.href = url;
      link.download = archive.filename;
      document.body.append(link);
      try { link.click(); } finally { link.remove(); }
      saveStatus.textContent = 'Download requested. Check your browser’s downloads for the saved lesson. Your answers are still here.';
    } catch {
      saveStatus.textContent = 'The lesson file could not be prepared. Your answers are still here; try saving again.';
    } finally {
      if (url) setTimeout(() => URL.revokeObjectURL(url), 10000);
    }
  });

  input.addEventListener('click', () => {
    clearPreview('Choose a saved lesson to preview it. Your current lesson is unchanged.');
  });
  input.addEventListener('cancel', () => {
    clearPreview('File selection canceled. Your current lesson is unchanged.');
  });
  input.addEventListener('change', async () => {
    const file = input.files?.[0];
    clearPreview(undefined, false);
    if (!file) {
      restoreStatus.textContent = 'No file selected. Your current lesson is unchanged.';
      return;
    }
    const ticket = generation;
    readingStamp = stamp();
    const beforeRead = readingStamp;
    restoreStatus.textContent = 'Reading the selected lesson…';
    try {
      if (file.size > LESSON_ARCHIVE_MAX_BYTES) throw new RangeError('Choose a saved lesson file no larger than 2 MiB.');
      const text = await file.text();
      if (ticket !== generation || !container.isConnected) return;
      if (beforeRead !== stamp()) return changed();
      const state = readLessonArchive(text, getDeck());
      pending = {state, stamp: beforeRead};
      readingStamp = null;
      const {answered, total, remaining} = state.summary;
      const position = state.presentation.phase === 'feedback'
        ? 'Returns to the explanation for your last answer.'
        : 'Returns to the next unanswered question.';
      query('#lesson-preview-summary').textContent = state.title + ' — saved ' + state.savedAt
        + '. ' + answered + ' of ' + total + ' questions answered; ' + remaining + ' remaining. ' + position;
      preview.hidden = false;
      restoreStatus.textContent = 'Preview ready. Your current lesson stays as it is until you resume.';
      query('#lesson-preview-title').focus();
    } catch (error) {
      if (ticket !== generation || !container.isConnected) return;
      if (beforeRead !== stamp()) return changed();
      clearPreview((error instanceof RangeError ? error.message : 'This lesson file could not be read.')
        + ' Your current lesson is unchanged.');
    }
  });
  query('#resume-lesson-cancel').addEventListener('click', () => {
    clearPreview('Resume canceled. Your current lesson is unchanged.');
    input.focus();
  });
  query('#resume-lesson-confirm').addEventListener('click', () => {
    if (!pending || !container.isConnected) return;
    if (pending.stamp !== stamp()) {
      changed();
      input.focus();
      return;
    }
    const state = pending.state;
    clearPreview();
    resumeLesson(state);
    refresh();
    restoreStatus.textContent = 'Lesson resumed. Continue from the saved question or feedback.';
  });
  refresh();
  return Object.freeze({refresh});
}

import { DEFAULT_BKT, initialMastery, selectNextItem, updateMastery } from './knowledge.mjs';

export const LESSON_ARCHIVE_MAX_BYTES = 2 * 1024 * 1024;
const LESSON_ARCHIVE_FORMAT = 'recallweave.unfinished-lesson';
const LESSON_ARCHIVE_MODEL = Object.freeze({name: 'recallweave-bkt-v1', parameters: DEFAULT_BKT});

function lessonRecord(value, keys) {
  return value !== null && typeof value === 'object' && !Array.isArray(value)
    && JSON.stringify(Object.keys(value).sort()) === JSON.stringify([...keys].sort());
}

// Compare the already admitted source, including content and array order, without
// depending on JSON object key order. No archived content becomes a loaded deck.
function lessonCanonical(value, depth = 0) {
  if (depth > 16) throw new RangeError('This unfinished lesson has invalid course or model data.');
  if (Array.isArray(value)) return '[' + value.map(entry => lessonCanonical(entry, depth + 1)).join(',') + ']';
  if (value !== null && typeof value === 'object') {
    const prototype = Object.getPrototypeOf(value);
    if (prototype !== Object.prototype && prototype !== null) {
      throw new RangeError('This unfinished lesson has invalid course or model data.');
    }
    return '{' + Object.keys(value).sort().map(key =>
      JSON.stringify(key) + ':' + lessonCanonical(value[key], depth + 1)).join(',') + '}';
  }
  if (value === null || typeof value === 'string' || typeof value === 'boolean'
      || (typeof value === 'number' && Number.isFinite(value))) return JSON.stringify(value);
  throw new RangeError('This unfinished lesson has invalid course or model data.');
}

function lessonReplay(document, deck) {
  if (!lessonRecord(document, ['format', 'version', 'savedAt', 'deck', 'model', 'firstAnswers', 'mastery', 'presentation'])
      || document.format !== LESSON_ARCHIVE_FORMAT || document.version !== 1) {
    throw new RangeError('This unfinished lesson format is not supported.');
  }
  if (typeof document.savedAt !== 'string' || document.savedAt.length !== 24
      || !Number.isFinite(Date.parse(document.savedAt))
      || new Date(document.savedAt).toISOString() !== document.savedAt) {
    throw new RangeError('This unfinished lesson has an invalid save time.');
  }
  if (lessonCanonical(document.deck) !== lessonCanonical(deck)) {
    throw new RangeError('This lesson belongs to a different course or course version. Load its course, then choose this file again.');
  }
  if (lessonCanonical(document.model) !== lessonCanonical(LESSON_ARCHIVE_MODEL)) {
    throw new RangeError('This lesson uses a different learning model.');
  }
  if (!Array.isArray(document.firstAnswers)) {
    throw new RangeError('This lesson has invalid first answers.');
  }
  if (document.firstAnswers.length >= deck.items.length) {
    throw new RangeError('This lesson is complete. Use a completed learning trace to save or restore it.');
  }

  const asked = new Set();
  const mastery = initialMastery(deck.concepts);
  const answers = [];
  for (const answer of document.firstAnswers) {
    const item = selectNextItem(deck.items, asked, mastery);
    if (!lessonRecord(answer, ['item', 'choice']) || !item || answer.item !== item.id
        || !Number.isInteger(answer.choice) || answer.choice < 0 || answer.choice >= item.options.length) {
      throw new RangeError('This lesson has invalid first answers or question order.');
    }
    const correct = answer.choice === item.answer;
    asked.add(item.id);
    mastery[item.concept] = updateMastery(mastery[item.concept], correct);
    answers.push(Object.freeze({item: item.id, concept: item.concept, choice: answer.choice, correct}));
  }
  if (!lessonRecord(document.mastery, deck.concepts)
      || deck.concepts.some(concept => !Number.isFinite(document.mastery[concept]) || document.mastery[concept] !== mastery[concept])) {
    throw new RangeError('This lesson does not preserve the original model estimates.');
  }

  const nextItem = selectNextItem(deck.items, asked, mastery);
  const presentation = document.presentation;
  if (!lessonRecord(presentation, ['phase', 'itemId', 'optionOrders'])
      || !['question', 'feedback'].includes(presentation.phase)
      || presentation.itemId !== (presentation.phase === 'question' ? nextItem?.id : answers.at(-1)?.item)
      || (presentation.phase === 'feedback' && answers.length === 0)
      || !lessonRecord(presentation.optionOrders, deck.items.map(item => item.id))) {
    throw new RangeError('This lesson has invalid question or feedback presentation.');
  }
  const optionOrders = Object.fromEntries(deck.items.map(item => {
    const order = presentation.optionOrders[item.id];
    if (!Array.isArray(order) || order.length !== item.options.length
        || new Set(order).size !== order.length
        || !order.every(index => Number.isInteger(index) && index >= 0 && index < item.options.length)) {
      throw new RangeError('This lesson has invalid answer display order.');
    }
    return [item.id, Object.freeze([...order])];
  }));

  return Object.freeze({
    savedAt: document.savedAt,
    title: deck.title,
    answers: Object.freeze(answers),
    mastery: Object.freeze(mastery),
    presentation: Object.freeze({
      phase: presentation.phase, itemId: presentation.itemId,
      optionOrders: Object.freeze(optionOrders)
    }),
    nextItemId: nextItem.id,
    summary: Object.freeze({
      answered: answers.length,
      total: deck.items.length,
      remaining: deck.items.length - answers.length,
      correctFirst: answers.filter(answer => answer.correct).length
    })
  });
}

/** Validate bounded JSON against the loaded deck; return immutable state without applying it. */
export function readLessonArchive(text, deck) {
  if (typeof text !== 'string' || text.length > LESSON_ARCHIVE_MAX_BYTES
      || new TextEncoder().encode(text).byteLength > LESSON_ARCHIVE_MAX_BYTES) {
    throw new RangeError('Choose an unfinished lesson file no larger than 2 MiB.');
  }
  let document;
  try { document = JSON.parse(text); }
  catch { throw new RangeError('This file is not valid unfinished lesson JSON.'); }
  return lessonReplay(document, deck);
}

/** Save a started, unfinished first session, including current presentation and every option order. */
export function createLessonArchive({deck, answers, mastery, presentation, savedAt = new Date()}) {
  if (!Array.isArray(answers) || answers.some(answer => answer === null || typeof answer !== 'object')) {
    throw new RangeError('This lesson has invalid first answers.');
  }
  const when = new Date(savedAt);
  if (!Number.isFinite(when.getTime())) throw new RangeError('An unfinished lesson needs a valid save time.');
  const document = {
    format: LESSON_ARCHIVE_FORMAT,
    version: 1,
    savedAt: when.toISOString(),
    deck,
    model: LESSON_ARCHIVE_MODEL,
    firstAnswers: answers.map(answer => ({item: answer.item, choice: answer.choice})),
    mastery,
    presentation
  };
  // Validate the original state before JSON can discard non-JSON values or extra keys.
  lessonReplay(document, deck);
  const text = JSON.stringify(document, null, 2) + '\n';
  readLessonArchive(text, deck);
  return Object.freeze({
    filename: 'recallweave-unfinished-lesson-' + when.toISOString().slice(0, 10) + '.json',
    mediaType: 'application/json;charset=utf-8',
    text
  });
}

